def transform(grid):
    h, w = len(grid), len(grid[0])

    def bands(n, separators):
        result = []
        start = 0
        for s in separators:
            if start < s:
                result.append((start, s))
            start = s + 1
        if start < n:
            result.append((start, n))
        return result

    rb = bands(h, [r for r in range(h) if all(v == 8 for v in grid[r])])
    cb = bands(w, [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))])

    nr, nc = len(rb), len(cb)
    seeds = {2: set(), 3: set()}
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            if any(grid[r][c] == 2 for r in range(r0, r1) for c in range(c0, c1)):
                seeds[2].add((i, j))
            if any(grid[r][c] == 3 for r in range(r0, r1) for c in range(c0, c1)):
                seeds[3].add((i, j))

    filled = {2: set(seeds[2]), 3: set(seeds[3])}
    for color in (2, 3):
        points = seeds[color]
        for i, j in points:
            same_row = [jj for ii, jj in points if ii == i]
            same_col = [ii for ii, jj in points if jj == j]
            if same_row:
                for jj in range(min(same_row), max(same_row) + 1):
                    filled[color].add((i, jj))
            if same_col:
                for ii in range(min(same_col), max(same_col) + 1):
                    filled[color].add((ii, j))

    out = [row[:] for row in grid]
    for i, (r0, r1) in enumerate(rb):
        for j, (c0, c1) in enumerate(cb):
            has2, has3 = (i, j) in filled[2], (i, j) in filled[3]
            if has2 or has3:
                color = 6 if has2 and has3 else (2 if has2 else 3)
                for r in range(r0, r1):
                    for c in range(c0, c1):
                        out[r][c] = color
    return out
